import{_ as t,a as r,o as a,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"List Return Messages","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-return-messages","title":"List Return Messages","description":"List the conversation messages of a return (RMA) request owned by the authenticated customer, newest first.","query":"query CustomerReturnMessages($returnId: Int!) {\\n  customerReturnMessages(returnId: $returnId) {\\n    _id\\n    rmaId\\n    message\\n    isAdmin\\n    attachment\\n    attachmentUrl\\n    createdAt\\n  }\\n}\\n","variables":"{\\n  \\"returnId\\": 12\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"customerReturnMessages\\": [\\n      {\\n        \\"_id\\": 88,\\n        \\"rmaId\\": 12,\\n        \\"message\\": \\"We have received your request and will inspect the item.\\",\\n        \\"isAdmin\\": true,\\n        \\"attachment\\": null,\\n        \\"attachmentUrl\\": null,\\n        \\"createdAt\\": \\"2026-07-20T10:40:00+00:00\\"\\n      },\\n      {\\n        \\"_id\\": 87,\\n        \\"rmaId\\": 12,\\n        \\"message\\": \\"The hoodie zipper is broken.\\",\\n        \\"isAdmin\\": false,\\n        \\"attachment\\": \\"rma/12/messages/zipper.jpg\\",\\n        \\"attachmentUrl\\": \\"https://example.com/storage/rma/12/messages/zipper.jpg\\",\\n        \\"createdAt\\": \\"2026-07-20T10:20:00+00:00\\"\\n      }\\n    ]\\n  }\\n}\\n","commonErrors":[{"error":"returnId required","cause":"The returnId argument is missing","solution":"Provide the numeric id of a return owned by the authenticated customer"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The return does not exist or is not owned by the authenticated customer","solution":"Only return IDs belonging to the logged-in customer can be queried"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/queries/list-return-messages.md","filePath":"api/graphql-api/shop/returns/queries/list-return-messages.md","lastUpdated":1786429091000}'),n={name:"api/graphql-api/shop/returns/queries/list-return-messages.md"};function o(d,e,i,c,u,h){return a(),r("div",null,e[0]||(e[0]=[s('<h1 id="list-return-messages" tabindex="-1">List Return Messages <a class="header-anchor" href="#list-return-messages" aria-label="Permalink to &quot;List Return Messages&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>customerReturnMessages</code> query lists the conversation thread of a return (RMA) request, newest first. The return must belong to the authenticated customer. Each message is flagged with <code>isAdmin</code> so a client can tell who sent it, and carries an optional attachment.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This query requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>returnId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the return whose messages to list. Must belong to the authenticated customer.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><p>The query returns a plain list of messages, not a cursor connection — there is no <code>edges</code>, <code>pageInfo</code>, or <code>totalCount</code> to select, and no pagination arguments. The whole thread comes back in one response.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>Int!</code></td><td>Numeric message id.</td></tr><tr><td><code>rmaId</code></td><td><code>Int!</code></td><td>Id of the return the message belongs to.</td></tr><tr><td><code>message</code></td><td><code>String!</code></td><td>The message text.</td></tr><tr><td><code>isAdmin</code></td><td><code>Boolean!</code></td><td><code>true</code> if sent by the store, <code>false</code> if sent by the customer.</td></tr><tr><td><code>attachment</code></td><td><code>String</code></td><td>Stored attachment path, or <code>null</code>.</td></tr><tr><td><code>attachmentUrl</code></td><td><code>String</code></td><td>Public URL of the attachment, or <code>null</code>.</td></tr><tr><td><code>createdAt</code></td><td><code>DateTime!</code></td><td>Message timestamp.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/mutations/send-return-message.html">Send a Return Message</a></li><li><a href="/api/graphql-api/shop/returns/queries/view-return.html">View Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>',12)]))}const p=t(n,[["render",o]]);export{m as __pageData,p as default};
